# -*- coding: utf-8 -*-
import json, re
from collections import Counter, defaultdict
d=json.load(open('grid.json',encoding='utf-8')); rows=d['rows']
data=[(i+2, r) for i,r in enumerate(rows[1:])]
def g(r,c): return str(r[c-1]).strip()

print('=== 1. A 编码 ↔ B/E/G/I/K 一致性 ===')
mis=defaultdict(list)
for ln,r in data:
    p=g(r,1).split('-')
    if len(p)!=6: mis['段数'].append((ln,g(r,1))); continue
    if p[1]!=g(r,9): mis['A2≠I'].append((ln,g(r,1),g(r,9),g(r,10)))
    if p[2]!=g(r,7): mis['A3≠G'].append((ln,g(r,1),g(r,7),g(r,8)))
    if p[3]!=g(r,5): mis['A4≠E'].append((ln,g(r,1),g(r,5),g(r,6)))
    if p[4]!=g(r,2): mis['A5≠B'].append((ln,g(r,1),g(r,2)))
    if p[5]!=g(r,11): mis['A6≠K'].append((ln,g(r,1),g(r,11)))
for k,v in mis.items():
    print(' ',k, len(v))
    for x in v[:12]: print('    ',x)

print('\n=== 2. A 编码重复 ===')
c=Counter(g(r,1) for ln,r in data)
dup={k:v for k,v in c.items() if v>1}
print(' 重复编码数:', len(dup), '涉及行数:', sum(dup.values()))
for k,v in dup.items():
    print('  ',k,'x',v,'-> 行', [ln for ln,r in data if g(r,1)==k])

print('\n=== 3. 层级名称一对一 ===')
pairs=[('环节',9,10),('环节+步骤',(9,7),(10,8)),('环节+步骤+操作',(9,7,5),(10,8,6))]
def key(r,cols):
    return tuple(g(r,c) for c in (cols if isinstance(cols,tuple) else (cols,)))
for name,kc,nc in pairs:
    k2n=defaultdict(set); n2k=defaultdict(set)
    for ln,r in data:
        k2n[key(r,kc)].add(key(r,nc)); n2k[key(r,nc)].add(key(r,kc))
    bad1={k:v for k,v in k2n.items() if len(v)>1}
    bad2={k:v for k,v in n2k.items() if len(v)>1}
    print(' ',name,'一码多名:',len(bad1),' 一名多码:',len(bad2))
    for k,v in list(bad2.items())[:8]: print('    名',k,'-> 码',v)

print('\n=== 4. 编号连续性（环节/步骤/操作/子项 是否从01连续向上）===')
huan=sorted({g(r,9) for ln,r in data}); print(' 环节号:',huan)
steps=defaultdict(set)
for ln,r in data: steps[g(r,9)].add(g(r,7))
for k in huan: print('  环节',k,'步骤:',sorted(steps[k]))
ops=defaultdict(set)
for ln,r in data: ops[(g(r,9),g(r,7))].add(g(r,5))
for k in sorted(ops): print('  步骤',k,'操作:',sorted(ops[k]))
subs=defaultdict(list)
for ln,r in data: subs[(g(r,9),g(r,7),g(r,5))].append(g(r,2))
print('\n 子项号断号/重复检查:')
for k in sorted(subs):
    v=sorted(set(subs[k]))
    exp=['%02d'%i for i in range(1,len(v)+1)]
    if v!=exp: print('   ',k,'实际',v,'期望',exp)
