# -*- coding: utf-8 -*-
import json
from collections import Counter, defaultdict
d=json.load(open('grid.json',encoding='utf-8')); rows=d['rows']
data=[(i+2, r) for i,r in enumerate(rows[1:])]
def g(r,c): return str(r[c-1]).strip()

print('=== 5. 空值检查 ===')
for c,name in [(1,'A'),(2,'B'),(3,'C子项'),(5,'E'),(6,'F'),(7,'G'),(8,'H'),(9,'I'),(10,'J'),(11,'K'),(12,'L'),(13,'M'),(14,'N'),(15,'O'),(16,'P'),(17,'Q'),(18,'R'),(19,'S'),(21,'U错误类型'),(22,'V累计'),(23,'W应用'),(24,'X显示'),(30,'AD缺省')]:
    e=[ln for ln,r in data if g(r,c)=='']
    if e: print('  %s 空 %d 行: %s'%(name,len(e),e[:15]))
print('  D语音提示 空:', sum(1 for ln,r in data if g(r,4)=='') ,'/',len(data))

print('\n=== 6. 开关列值域 ===')
for c,name in [(21,'U错误类型'),(22,'V是否累计'),(23,'W是否应用'),(24,'X是否显示'),(15,'O关键步骤'),(30,'AD缺省')]:
    print('  ',name, dict(Counter(g(r,c) for ln,r in data)))

print('\n=== 7. 同一操作内 Q / R / O 是否唯一 ===')
for col,label in [(17,'Q'),(18,'R'),(15,'O'),(12,'L'),(8,'H')]:
    bad=defaultdict(set)
    for ln,r in data: bad[(g(r,9),g(r,7),g(r,5))].add(g(r,col))
    b={k:v for k,v in bad.items() if len(v)>1}
    print('  %s 冲突的操作数: %d'%(label,len(b)))
    for k,v in list(b.items())[:10]:
        print('     ',k, v, '行', [ln for ln,r in data if (g(r,9),g(r,7),g(r,5))==k])

print('\n=== 8. P 与 Q：|P|>Q（单项扣分超过该操作满分）===')
over=[(ln,g(r,1),g(r,3)[:24],g(r,16),g(r,17)) for ln,r in data if abs(float(g(r,16)))>float(g(r,17))]
print(' 共', len(over), '行')
for x in over: print('   ',x)

print('\n=== 9. 权重 Y-AC 每行合计 ===')
bad=[]
for ln,r in data:
    try:
        s=sum(float(g(r,c)) for c in range(25,30))
    except Exception as e:
        bad.append((ln,'非数值')); continue
    if abs(s-1)>1e-9: bad.append((ln,round(s,4), [g(r,c) for c in range(25,30)]))
print(' 合计≠1 的行:', len(bad))
for x in bad[:15]: print('   ',x)
print(' 权重取值:', dict(Counter(tuple(g(r,c) for c in range(25,30)) for ln,r in data)))
EOF

