# -*- coding: utf-8 -*-
import json
from collections import Counter, defaultdict
d=json.load(open('grid.json',encoding='utf-8')); rows=d['rows']
data=[(i+2, r) for i,r in enumerate(rows[1:])]
def g(r,c): return str(r[c-1]).strip()

print('=== 10. 应用/显示 异常行 ===')
for ln,r in data:
    if g(r,23)!='是' or g(r,24)!='是':
        print('  行%d W应用=%s X显示=%s | %s | %s | %s'%(ln,g(r,23),g(r,24),g(r,1),g(r,3)[:26],g(r,21)))

print('\n=== 11. U 错误类型为空 ===')
for ln,r in data:
    if g(r,21)=='':
        print('  行%d %s | %s | P%s Q%s | V%s'%(ln,g(r,1),g(r,3)[:30],g(r,16),g(r,17),g(r,22)))

print('\n=== 12. 严重错误 16 行 ===')
for ln,r in data:
    if g(r,21)=='严重错误': print('  行%d %s P%s Q%s %s'%(ln,g(r,1),g(r,16),g(r,17),g(r,3)[:30]))

print('\n=== 13. 同一操作内子项重名 ===')
m=defaultdict(list)
for ln,r in data: m[(g(r,9),g(r,7),g(r,5),g(r,3))].append(ln)
dup={k:v for k,v in m.items() if len(v)>1}
print(' 重名组数:', len(dup))
for k,v in dup.items(): print('  ',k[0:3],k[3][:26],'行',v)

print('\n=== 14. 高频重复文案（跨操作）===')
c=Counter(g(r,3) for ln,r in data)
for k,v in c.most_common(12): print('  %-30s %d'%(k,v))

print('\n=== 15. 行序是否按编码升序 ===')
codes=[g(r,1) for ln,r in data]
inv=[]
for i in range(1,len(codes)):
    if codes[i] < codes[i-1]: inv.append((data[i][0], codes[i-1], codes[i]))
print(' 逆序断点数:', len(inv))
for x in inv: print('   行%d: %s -> %s'%x)
