print('\n=== 名称一对一 ===')
for name,kc,nc in [('环节',9,10),('环节+步骤',(9,7),(10,8)),('环节+步骤+操作',(9,7,5),(10,8,6))]:
    k2n=defaultdict(set); n2k=defaultdict(set)
    for ln,r in data:
