    for k,v in b2.items(): print('    名',k,'->码',v)

print('\n=== 编号连续性 ===')
huan=sorted({g(r,9) for ln,r in data}); print(' 环节:',huan)
steps=defaultdict(set); ops=defaultdict(set)
