    if p[3]!=g(r,5): mis['A4≠E'].append(ln)
    if p[4]!=g(r,2): mis['A5≠B'].append(ln)
    if p[5]!=g(r,11): mis['A6≠K'].append(ln)
    if p[0]!=g(r,13): mis['A1≠M'].append(ln)
print('编码一致性:',{k:(len(v),v[:8]) for k,v in mis.items()} or '全部一致')
c=Counter(g(r,1) for ln,r in data)
print('重复编码:',{k:v for k,v in c.items() if v>1} or '无')
for name,kc,nc in [('环节',9,10),('环节+步骤',(9,7),(10,8)),('环节+步骤+操作',(9,7,5),(10,8,6))]:
    k2n=defaultdict(set); n2k=defaultdict(set)
    for ln,r in data:
        kk=tuple(g(r,x) for x in (kc if isinstance(kc,tuple) else (kc,)))
        nn=tuple(g(r,x) for x in (nc if isinstance(nc,tuple) else (nc,)))
        k2n[kk].add(nn); n2k[nn].add(kk)
    print(name,'一码多名',len({k:v for k,v in k2n.items() if len(v)>1}),'一名多码',len({k:v for k,v in n2k.items() if len(v)>1}))
    for k,v in {k:v for k,v in n2k.items() if len(v)>1}.items(): print('    名',k,'->',v)
ops=defaultdict(set)
for ln,r in data: ops[(g(r,9),g(r,7))].add(g(r,5))
bad=[(k,sorted(v)) for k,v in ops.items() if sorted(v)!=['%02d'%i for i in range(1,len(v)+1)]]
print('操作编号断号:',bad or '无')
sub=defaultdict(list)
for ln,r in data: sub[(g(r,9),g(r,7),g(r,5))].append(g(r,2))
bad2=[(k,sorted(set(v))) for k,v in sub.items() if sorted(set(v))!=['%02d'%i for i in range(1,len(set(v))+1)]]
print('子项编号异常:',bad2 or '无')
for col,label in [(17,'Q'),(18,'R'),(15,'O'),(12,'L'),(8,'H')]:
    m=defaultdict(set)
    for ln,r in data: m[(g(r,9),g(r,7),g(r,5))].add(g(r,col))
    b={k:v for k,v in m.items() if len(v)>1}
    print(' 操作内 %s 冲突:'%label, b or '无')
codes=[g(r,1) for ln,r in data]
print('行序逆序:',[(data[i][0],codes[i-1],codes[i]) for i in range(1,len(codes)) if codes[i]<codes[i-1]] or '无')
print('权重异常行:',sum(1 for ln,r in data if abs(sum(float(g(r,c)) for c in range(25,30))-1)>1e-9))
print('U 空:',[ln for ln,r in data if g(r,21)==''] or '无')
print('W/X 异常:',[(ln,g(r,23),g(r,24)) for ln,r in data if g(r,23)!='是' or g(r,24)!='是'] or '无')
print('Q 合计(去重):',sum({(g(r,9),g(r,7),g(r,5)):float(g(r,17)) for ln,r in data}.values()))
print('操作数:',len({(g(r,9),g(r,7),g(r,5)) for ln,r in data}),' 步骤',len({(g(r,9),g(r,7)) for ln,r in data}),' 环节',len({g(r,9) for ln,r in data}))
